+	}
+	for _, want := range []string{"UNIQUE (installation_id, source_id)", "PRIMARY KEY (installation_id, repository_id, metric_day, team, author_login)", "FORCE ROW LEVEL SECURITY", "current_setting('px1.installation_id', true)"} {
